/* Shared DOM product prototype. State lives only in this page and resets on reload. */
(() => {
  'use strict';
  const D=window.P2_MOCK, $=s=>document.querySelector(s);
  const esc=value=>String(value).replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
  const badge=(text,tone='blue')=>`<span class="badge ${tone}">${esc(text)}</span>`;
  const facts=rows=>`<dl class="fact-grid">${rows.map(([a,b])=>`<div><dt>${esc(a)}</dt><dd>${b}</dd></div>`).join('')}</dl>`;
  const button=(id,text,{disabled=false,tone='secondary',small=false}={})=>`<button type="button" class="button ${tone}${small?' small':''}" id="${id}"${disabled?' disabled':''}>${text}</button>`;
  let view='case',toastTimer,dialogCallback=null;
  const evidencePlan='渠道负责人回查四项资料并附回 CI-001，由运营复核后再人工审核；未 Confirm 不生成 TASK-001。';
  const fresh=()=>({normal:{status:'AI Processing',sent:false,verified:false,closed:false,draft:D.reply,resultNote:'',closeNote:''},handoff:{accepted:false,started:false,timeout:false,escalated:false,note:''},voc:{evidenceReady:false,decision:'Need Evidence',note:evidencePlan,taskPreview:false}});
  let state=fresh();
  function toast(message){clearTimeout(toastTimer);$('#toast').textContent=message;$('#toast').hidden=false;toastTimer=setTimeout(()=>$('#toast').hidden=true,4500);}
  function showDialog(title,description,fields,submit,callback,{readOnly=false}={}){
    $('#dialog-title').textContent=title;$('#dialog-description').textContent=description;$('#dialog-fields').innerHTML=fields;$('#dialog-submit').textContent=submit;$('#dialog-submit').hidden=readOnly;$('#dialog-cancel').textContent=readOnly?'关闭':'取消';dialogCallback=callback;$('#action-dialog').showModal();
  }
  const check=(name,text)=>`<label class="check-label"><input type="checkbox" name="${name}" required><span>${text}</span></label>`;
  const note=(label='处理依据',value='')=>`<label><span class="field-label">${label}</span><textarea class="note-input" name="note" required placeholder="填写本次模拟判断的依据">${esc(value)}</textarea></label>`;
  function heading(title,subtitle,status,scene){return `<p class="breadcrumb">服务工作空间 / ${view==='case'?'Customer Case':view==='handoff'?'Human Handoff':'VOC Improvement'}</p><header class="page-heading"><div><h1>${title}</h1><p>${subtitle}</p></div><div class="heading-status">${status}</div></header>${scene}`;}
  function scene(text,detail,exception=false){return `<div class="scene-bar${exception?' exception':''}"><strong>${text}</strong><span>${detail}</span></div>`;}
  function caseQueue(handoff=false){const h=state.handoff,n=state.normal;return `<aside class="panel queue-panel"><div class="panel-heading"><h2>${handoff?'待接收队列':'当前服务 Case'}</h2><small>Mock</small></div><div class="queue-item selected" aria-current="true"><strong>${D.caseId}</strong><h3>${handoff?'退回依据差异待核查':'申请退回原因查询'}</h3>${badge(handoff?(h.accepted?'Human Processing':'Pending Handoff'):n.status,handoff&&!h.accepted?'amber':'blue')}<p>关联 ${D.applicationId}</p><p>${handoff?'接收队列：服务 A 核查队列':'责任方：客服 A（模拟）'}</p><p>${handoff?(h.accepted?'接收于 10:26（模拟）':h.timeout?'接收超时 · 仍待接收':'等待 2 分钟（模拟）'):'最近处理 10:24（模拟）'}</p></div>${handoff?`<div class="queue-note"><strong>标准优先级 · 需核查</strong><p class="inline-note">未被接收前，服务队列责任人持续跟进。超时不能自动解决或关闭。</p></div>`:`<p class="queue-section-title">相关服务记录 · 在 VOC 中核查</p><a class="queue-related" href="?view=voc" data-view="voc"><strong>CASE-002 / CASE-003</strong>渠道材料清单疑似缺项</a><a class="queue-related" href="?view=voc" data-view="voc"><strong>CASE-004</strong>适用条件不同，排除合并</a><p class="queue-note">单次 Case 的完成，不自动生成组织改进任务。</p>`}</aside>`;}
  function renderCase(){const n=state.normal;
    return heading('申请退回原因查询',`${D.caseId} · ${D.applicationId} · 当前任务：说明原因与下一步`,badge(n.status,n.verified?'green':'blue')+badge('Application · Returned','amber'),scene('正常处理分支 · 业务事实与适用规则一致','AI 先查实际申请，再按需核对规则；不代客户重新提交'))+
    `<div class="execution-caption"><strong>本轮 AI 查询 / 建议已完成（Mock）</strong><span>${n.closed?'Case 已经结果验证与独立关闭检查':n.verified?'Case 已验证解决；仍待关闭检查':n.sent?'Case 等待客户结果验证；尚未解决':'Case 尚未解决：待回复与客户结果验证'}</span></div><ol class="execution-strip" aria-label="本轮 AI 查询与建议轨迹，不代表 Case 已解决（Mock）">${D.steps.map(([title,value],i)=>`<li><strong><span class="step-index">${i+1}</span>${title}</strong><p>${value}</p></li>`).join('')}</ol><div class="work-area">${caseQueue()}<section class="panel"><div class="detail-metadata"><span>当前责任方<strong>客服 A（模拟）</strong></span><span>服务条件<strong>服务 A / 地区甲</strong></span><span>访问检查<strong>身份与范围已核验（Mock）</strong></span><span>更新<strong>${D.updatedAt}</strong></span></div><div class="case-columns"><div><section class="detail-section"><div class="section-title"><h2>客户对话与当前诉求</h2><small>只处理这次咨询</small></div><p class="history">历史背景：${D.history}</p><p class="conversation-label">企业客户（模拟） · 10:22</p><div class="customer-message">${D.customerQuestion}</div>${n.sent?`<div class="conversation-response"><strong>客服回复 · 本地模拟已发送</strong><p>${esc(n.draft)}</p></div>`:''}</section><section class="detail-section"><div class="section-title"><h2>AI 建议回复</h2>${badge('无需差异核查','green')}</div><textarea id="reply-draft" class="reply-draft" aria-label="建议回复内容"${n.sent?' readonly':''}>${esc(n.draft)}</textarea><div class="reply-toolbar"><span class="help">基于业务记录 + 适用规则；本次仅提供指导</span>${button('send-reply',n.sent?'已模拟发送':'模拟发送回复',{disabled:n.sent,tone:'primary'})}</div></section><section class="result-section"><h3>当前服务结果 · ${esc(n.status)}</h3><p>${n.closed?'关闭检查与依据已在本地演示中记录；申请仍为 Returned。':n.verified?'客户已在模拟分支中确认理解原因与下一步；可以进行关闭检查。':n.sent?'等待客户明确确认；已回复或客户静默均不计为已解决。':'建议尚未交付；不能仅因生成回复就标记解决。'}</p>${n.verified?`<p class="result-record"><strong>结果确认 · 客服 A（模拟）</strong><span>${esc(n.resultNote)}</span></p>`:''}${n.closed?`<p class="result-record"><strong>关闭依据 · 客服 A（模拟）</strong><span>${esc(n.closeNote)}</span></p>`:''}<div class="button-row">${button('verify-case','记录客户结果确认',{disabled:!n.sent||n.verified,tone:'primary',small:true})}${button('close-case','检查并关闭 Case',{disabled:!n.verified||n.closed,small:true})}</div></section></div><div><section class="detail-section"><div class="section-title"><h2>Business Record</h2>${badge('业务事实','blue')}</div>${facts([['关联申请',esc(D.applicationId)],['申请状态',badge(D.applicationStatus,'amber')],['具体退回原因',`<strong>${D.returnReason}</strong>`],['记录时间',D.recordTime]])}<p class="source-line">来源：${D.businessSource} · 仅为 Mock 记录</p><div class="button-row" style="margin-top:10px">${button('business-record','查看退回记录',{small:true})}</div></section><section class="detail-section"><div class="section-title"><h2>Knowledge Context</h2><small>按需调用 P1 能力</small></div><p class="rule-excerpt">${D.normalRule}</p>${facts([['适用规范',esc(D.knowledgeTitle)],['来源',esc(D.knowledgeSource)],['适用限制','仅服务 A / 地区甲；条件改变须重新核对']])}<div class="button-row" style="margin-top:11px">${button('knowledge-evidence','查看知识依据',{small:true})}</div><div class="boundary">知识说明适用要求，业务记录说明这次实际发生了什么。P1 / P2 尚未真实集成。</div></section></div></div></section></div>`;
  }
  function renderHandoff(){const h=state.handoff,cs=h.accepted?'Human Processing':'Pending Handoff',hs=h.started?'Human Processing':h.accepted?'Accepted':'Pending Assignment';
    return heading('申请退回，依据差异待核查',`${D.caseId} · 独立异常分支 · 接收后继续核查`,badge(cs,h.accepted?'blue':'amber')+badge('Application · Returned','amber'),scene('异常模拟分支 · 与正常 Case 视图不是同一条执行历史','退回记录不变；检索清单的适用地区 / 版本仍待核实',true))+
    `<ol class="handoff-steps" aria-label="Handoff 状态"><li class="${!h.accepted?'active':''}">Pending Assignment<small>等待明确接收，队列仍负责</small></li><li class="${h.accepted&&!h.started?'active':''}">Accepted<small>接收回执，不是解决结果</small></li><li class="${h.started?'active':''}">Human Processing<small>开始核查并记录处理</small></li></ol><div class="work-area">${caseQueue(true)}<div class="handoff-grid"><section class="panel"><div class="panel-heading"><h2>Handoff Packet · 接手前先看这里</h2><small>版本 HP-001（Mock）</small></div><section class="detail-section"><p class="kicker">客户问题与已确认条件</p><p class="packet-summary">申请被退回，希望了解实际原因和处理办法。</p><dl class="packet-facts"><div><dt>客户 / 访问范围</dt><dd>身份与申请访问条件已核验</dd></div><div><dt>申请编号</dt><dd>${D.applicationId}</dd></div><div><dt>服务与地区</dt><dd>服务 A / 地区甲</dd></div></dl><p class="source-line">历史：曾咨询材料并提交；本次不能要求客户从头复述已确认的信息。</p></section><section class="detail-section"><div class="section-title"><h3>已完成查询 · 两侧证据分开保留</h3>${button('handoff-evidence','查看证据',{small:true})}</div><div class="evidence-compare"><article><h3>Business Record</h3><p><strong>Returned</strong><br>${D.returnReason}</p><small>${D.businessSource}<br>${D.recordTime}</small></article><article><h3>Knowledge Context</h3><p>${D.exceptionRule}</p><small>Mock 渠道清单 · 原始版本待核实<br>不作为确定结论</small></article></div><div class="boundary warning"><strong>AI 停止的原因：</strong>当前证据不足以解释两侧差异，不能认定知识过期或业务人员出错。</div></section><section class="detail-section"><div class="section-title"><h3>接手后的下一步</h3><small>需要有权限的人核查</small></div><ol class="next-actions"><li>核对清单来源、版本及实际适用范围。</li><li>回查原始退回记录与客户已提交材料。</li><li>形成可核对结论后反馈客户，继续验证当前服务结果。</li></ol><div class="boundary">客户看到：问题已记录、当前负责人和跟进安排；未接收时不提示“已有人处理”。</div></section></section><aside class="panel action-panel"><div class="panel-heading"><h2>接收与责任</h2>${badge(hs,h.accepted?'blue':'amber')}</div><section class="detail-section"><div class="owner-line"><span>当前 Case 责任</span><strong id="handoff-owner">${h.accepted?'客服 A（模拟）':'服务队列责任人（模拟）'}</strong></div><div class="owner-line"><span>接收队列</span>服务 A 核查队列</div><div class="owner-line"><span>接收情况</span>${h.accepted?'接收于 10:26（模拟）':h.timeout?'Mock 接收窗口已超时，仍未接收':'等待接收 · 2 分钟（模拟）'}</div>${h.accepted?`<div class="receipt" style="margin-top:12px">接收回执：客服 A · HP-001<br>原队列 → 客服 A · 10:26（模拟）<br>Case 为 Human Processing，未解决。</div>${button('begin-human',h.started?'已进入人工核查':'开始人工处理',{disabled:h.started,tone:'primary'})}`:`<label class="check-label" style="margin-top:12px"><input type="checkbox" id="receiver-permission"><span>我确认具备本次 Case 的访问与处理权限（模拟身份）。</span></label>${button('accept-case','模拟接收 Case',{disabled:true,tone:'primary'})}${button('simulate-unclaimed','演示接收超时',{disabled:h.timeout,small:true})}`}<p class="inline-note">责任只有在有效接收后移交；Accepted 不等于 Resolved。</p></section><section class="detail-section"><div class="section-title"><h3>核查记录</h3><small>仅保存在本地演示</small></div><textarea class="note-input" id="human-note" aria-label="核查记录" placeholder="记录待核查事项与已取得依据"${!h.started?' disabled':''}>${esc(h.note)}</textarea>${button('save-human-note','保存模拟核查记录',{disabled:!h.started})}${button('escalate-case','升级给授权负责人',{disabled:h.escalated})}<p class="inline-note">${h.escalated?'模拟升级请求已记录；原责任方持续负责，未自动转移或关闭。':'升级不替代接收确认；未知结果不能写成已核实。'}</p></section></aside></div></div>`;
  }
  function renderVoc(){const v=state.voc,confirmed=v.decision==='Confirm',status=confirmed?'Confirm · 模拟审核通过':v.decision==='Need Evidence'?'Need Evidence · 待补证据':v.decision+' · 模拟决定';
    return heading('候选问题审核与组织改进',`${D.issueId} · 先核对证据，再决定是否进入改进`,badge(status,confirmed?'green':'amber'),scene(confirmed?'补证假设 + 人工 Confirm · 用户主动进入的模拟分支':'当前 CI-001 = Need Evidence · 尚未创建正式改进任务',confirmed?'TASK-001 仅作目标态预览，未实际创建、分派或执行':'缺少清单来源、版本、使用时间及适用条件',!confirmed))+
    `<div class="work-area"><aside class="panel queue-panel"><div class="panel-heading"><h2>Candidate Issues</h2><small>Mock</small></div><div class="queue-item selected"><strong>CI-001</strong><h3>渠道材料清单可能遗漏日期要求</h3>${badge(v.decision,confirmed?'green':'amber')}<p>关联 CASE-002 / CASE-003</p><p>审核：运营 A（模拟）</p><p>下一步：${confirmed?'查看条件任务预览':'补充清单原件与发布信息'}</p></div><p class="queue-note">AI 提供关联建议；人工决定问题准入。相似反馈不自动成为共同根因。</p></aside><div class="voc-columns"><div class="voc-primary"><section class="panel"><div class="panel-heading"><h2>CI-001 · 候选问题详情</h2>${badge('AI 建议，待业务核查','blue')}</div><section class="detail-section"><p class="issue-statement">${D.issueTitle}</p><div class="association-facts"><span>适用条件<strong>服务 A / 地区甲</strong></span><span>共同线索<strong>缺少签署日期</strong></span><span>来源与版本<strong>待回查</strong></span></div><div class="boundary warning">${v.evidenceReady?'仅在当前演示分支中假设证据已齐备；最终根因仍需在任务中复核。':'CASE-002 / CASE-003 的清单是否同源、同版尚未确认；不能直接认定渠道指引错误。'}</div></section><table class="event-table" aria-label="候选关联与排除证据"><thead><tr><th scope="col">服务记录</th><th scope="col">条件与退回</th><th scope="col">清单 / 原始事件</th><th scope="col">关联判断</th></tr></thead><tbody>${D.events.map(e=>`<tr class="${e.kind==='排除'||e.kind==='对照'?'excluded':''}"><td><strong>${e.id}</strong><small>${e.signal}</small></td><td>${e.scope}<small>${e.reason}</small></td><td>${e.source}<small>Mock Service Event · ${e.id.replace('CASE','EVT')}</small></td><td>${badge(e.kind,e.kind==='排除'?'red':e.kind==='对照'?'':'blue')}<small>${e.condition}</small></td></tr>`).join('')}</tbody></table><section class="detail-section"><div class="section-title"><h3>证据关联边界</h3>${button('voc-evidence','查看原始事件',{small:true})}</div><p class="help">CASE-004 服务与地区不同，排除聚合；CASE-001 为正常缺件对照，不证明渠道清单有误。关联建议需要人工核对业务条件与来源。</p></section></section><section class="panel stacked-panel"><div class="panel-heading"><h2>Outcome Review · 两层验证</h2><small>待执行计划，无运行数据</small></div><div class="detail-section outcome-grid"><article><h3>01 措施验收</h3><p>核查清单、授权修订、范围内渠道更新与发布记录，由独立验收人复核。</p><p class="inline-note">措施满足验收，才可能关闭改进任务。</p></article><article><h3>02 后续效果观察</h3><p>观察同类退回、旧清单引用与重复咨询；核对适用条件、样本覆盖及观察窗口。</p><p class="inline-note">没有真实数据，不展示下降比例或成效。</p></article></div></section></div><aside class="voc-side"><section class="panel"><div class="panel-heading"><h2>Human Review</h2><small>运营 A（模拟）</small></div><section class="detail-section"><div class="section-title"><h3>${v.evidenceReady?'模拟补证条件已具备':'为什么当前还不能 Confirm？'}</h3></div><ul class="review-missing">${D.missingEvidence.map(e=>`<li>${e}${v.evidenceReady?' · 模拟已核对':''}</li>`).join('')}</ul><p class="help">补证责任：渠道内容负责人（模拟）<br>审核 / 跟进：服务运营负责人（模拟）</p><div class="review-record" id="evidence-followup"><strong>${v.decision==='Need Evidence'&&!v.evidenceReady?'下一步补证 → 回到 CI-001 复核':'当前审核依据'}</strong>${v.decision==='Need Evidence'&&!v.evidenceReady?`<p>${evidencePlan}</p>${v.note!==evidencePlan?`<p class="review-note">本地审核备注：${esc(v.note)}</p>`:''}`:`<p>${esc(v.note)}</p>`}</div><div class="review-buttons">${button('confirm-issue','Confirm',{disabled:!v.evidenceReady||confirmed,tone:'primary'})}${button('need-evidence','Need Evidence')}${button('merge-issue','Merge',{disabled:true})}${button('reject-observe','Reject / Observe')}</div>${v.evidenceReady?'<p class="inline-note">证据齐备也须人工 Confirm，且不存在重复任务。</p>':''}<p class="inline-note">Merge 需选择并核验已有事项，本轮未实现；不创建重复任务。</p>${button('simulate-evidence','演示：假设补证完成',{disabled:v.evidenceReady,small:true})}</section></section><section class="panel stacked-panel"><div class="panel-heading"><h2>TASK-001 · 条件预览</h2><small>非已创建记录</small></div><section class="detail-section"><div class="task-placeholder"><h3>${confirmed?D.taskTitle:'当前不生成 Improvement Task'}</h3>${confirmed?`${badge('Pending Acceptance','amber')}<p class="inline-note">拟接收：服务运营负责人<br>协作：渠道内容 / 客服知识负责人<br>验收：服务规范负责人</p>`:`<p>假设补证完成 → 人工 Confirm → 无重复事项，才进入目标态任务设计。</p>`}${button('preview-task','查看模拟任务目标态',{disabled:!confirmed,small:true})}<p class="inline-note">指派不等于接收；预览不执行组织任务。</p></div></section></section></aside></div></div>`;
  }
  function render(){
    $('#workspace').innerHTML=view==='case'?renderCase():view==='handoff'?renderHandoff():renderVoc();
    document.querySelectorAll('[data-view]').forEach(a=>{if(a.closest('.sidebar')){if(a.dataset.view===view)a.setAttribute('aria-current','page');else a.removeAttribute('aria-current');}});
    $('#current-user').textContent=view==='voc'?'运营 A（模拟）':'客服 A（模拟）';
    $('#footer-boundary').textContent=view==='voc'?'Case 关闭、任务验收与效果观察分别管理':view==='handoff'?'交接未确认，原责任不消失':'Case 与业务申请分别管理';
    document.title=(view==='case'?'Customer Case':view==='handoff'?'Human Handoff':'VOC Improvement')+' · 企业服务工作台 · Mock';
  }
  function chooseView(next,push=true){view=['case','handoff','voc'].includes(next)?next:'case';if(push){const u=new URL(location.href);u.searchParams.set('view',view);history.pushState({},'',u);}render();window.scrollTo(0,0);}
  function originalEvidence(exception=false){showDialog('业务记录与知识依据 · Mock','以下为可回查的模拟来源，不是企业系统的实际调用记录。',facts([['申请',D.applicationId],['申请状态',badge('Returned','amber')],['退回原因',D.returnReason],['业务来源',D.businessSource],['记录时间',D.recordTime],['知识依据',esc(exception?D.exceptionRule:D.normalRule)],['适用边界',exception?'清单版本 / 地区仍待核实':'服务 A / 地区甲；条件变化后重新核对']]),'',null,{readOnly:true});}
  document.addEventListener('click',event=>{
    const nav=event.target.closest('a[data-view]');if(nav&&!event.metaKey&&!event.ctrlKey){event.preventDefault();chooseView(nav.dataset.view);return;}
    const id=event.target.closest('button')?.id;if(!id||event.target.closest('button').disabled)return;
    const n=state.normal,h=state.handoff,v=state.voc;
    if(id==='reset-demo'){state=fresh();render();toast('本地演示已重置；没有修改外部系统。');}
    if(id==='business-record'||id==='knowledge-evidence')originalEvidence(false);
    if(id==='handoff-evidence')originalEvidence(true);
    if(id==='send-reply'){const draft=$('#reply-draft').value.trim();if(!draft){toast('请先填写建议回复。');return;}n.draft=draft;n.sent=true;n.status='Waiting for Customer';render();toast('仅模拟发送；Case 等待客户结果确认，申请仍为 Returned。');}
    if(id==='verify-case'&&n.sent&&!n.verified)showDialog('记录当前咨询结果确认 · Mock','本例验证的是退回原因与处理步骤，不是底层申请开通。仅在明确结果依据满足时模拟进入 Resolved。',check('customer','模拟客户已明确确认理解退回原因与下一步。')+check('evidence','适用依据可核对，无待核实差异或未知外部写入。')+note('确认依据','客户（模拟）确认已理解缺少签署日期的原因与补件步骤。'),'模拟记录为 Resolved',form=>{n.resultNote=form.get('note');n.verified=true;n.status='Resolved';render();toast('本地 Case 已模拟验证解决；Application 仍 Returned。');});
    if(id==='close-case'&&n.verified&&!n.closed)showDialog('关闭检查 · Mock','只有当前咨询已经验证解决，且无未完成待办时，才模拟关闭；客户静默不能替代确认。',check('noPending','当前咨询无待核实差异、未知写入或其他待办。')+check('owner','责任人已核对客户确认依据，保留关闭记录。')+note('关闭依据','本次咨询目标已验证，无当前待办；申请仍需客户补件。'),'模拟关闭 Case',form=>{n.closeNote=form.get('note');n.closed=true;n.status='Closed';render();toast('本地 Case 已模拟关闭；申请状态保持 Returned。');});
    if(id==='accept-case'&&!h.accepted&&$('#receiver-permission')?.checked){h.accepted=true;render();toast('Mock 接收回执已记录；Case 为 Human Processing，尚未解决。');}
    if(id==='begin-human'&&h.accepted){h.started=true;render();toast('开始本地人工核查；接收责任已保留。');}
    if(id==='simulate-unclaimed'&&!h.accepted){h.timeout=true;h.escalated=true;render();toast('演示接收超时：仍 Pending Handoff，服务队列继续负责并升级。');}
    if(id==='save-human-note'&&h.started){const value=$('#human-note').value.trim();if(!value){toast('请填写核查事项或依据。');return;}h.note=value;render();toast('仅保存本地模拟核查记录；未验证结果，不标记解决。');}
    if(id==='escalate-case')showDialog('升级核查 · Mock','升级请求不代表新的负责人已经接收。原责任方持续负责，Case 不自动解决或关闭。',note('升级原因','清单适用范围与原始退回依据需要授权负责人核查。'),'记录模拟升级请求',()=>{h.escalated=true;render();toast('本地升级请求已记录；责任仍由当前队列 / 接收人承担。');});
    if(id==='voc-evidence')showDialog('候选关联的原始事件 · Mock','关联必须同时核对业务条件与来源，不能仅凭相似文本合并。',`<dl class="fact-grid">${D.events.map(e=>`<div><dt>${e.id}</dt><dd>${e.scope}；${e.reason}。${e.source}；${e.condition}。</dd></div>`).join('')}</dl>`,'',null,{readOnly:true});
    if(id==='simulate-evidence')showDialog('进入补证完成的假设分支','仅用于演示目标态，不表示资料已经真实取得。勾选全部条件后仍须人工 Confirm；不会自动创建或执行任务。',D.missingEvidence.map((e,i)=>check('evidence'+i,`仅模拟：已取得并核验${e}。`)).join('')+check('noDuplicate','仅模拟：已核验同范围没有重复的候选任务。'),'仅应用模拟补证条件',()=>{v.evidenceReady=true;v.decision='Need Evidence';v.taskPreview=false;v.note='仅在此演示分支假设四项补证已核对，并排除重复任务；仍等待人工 Confirm。';render();toast('模拟补证条件已应用；尚未 Confirm，仍不生成任务。');});
    if(id==='confirm-issue'&&v.evidenceReady&&v.decision!=='Confirm')showDialog('人工 Confirm · 模拟准入','确认有证据支持的问题值得处理，不代表最终根因查明。只有授权运营审核且无重复任务时才允许进入目标态预览。',check('reviewer','模拟运营负责人已审核问题范围、证据与拟接收责任方。')+check('unique','确认当前假设分支不存在同范围重复任务。')+note('准入依据','模拟补证支持指引存在可核查差异，进入核查并统一清单的任务设计；最终原因待复核。'),'模拟 Confirm',form=>{v.decision='Confirm';v.note=form.get('note');render();toast('模拟审核通过；TASK-001 仅可预览，尚未创建或执行。');});
    if(id==='need-evidence')showDialog('Need Evidence · 保留补证责任','CI-001 保持待补证；渠道内容负责人补齐四项资料并附回原候选问题，由运营负责人重新核验和人工审核。保存决定不生成 TASK-001。',note('待补证与责任安排',evidencePlan),'保存本地补证决定',form=>{v.decision='Need Evidence';v.evidenceReady=false;v.taskPreview=false;v.note=form.get('note');render();toast('CI-001 保持 Need Evidence；渠道负责人补证后回到原问题复核，未生成 TASK-001。');});
    if(id==='reject-observe')showDialog('Reject / Observe · 模拟审核决定','拒绝或观察不进入新改进任务执行；观察须保留复查条件与责任。',`<label><span class="field-label">审核动作</span><select class="text-input" name="decision"><option value="Observe">Observe · 保留观察</option><option value="Reject">Reject · 不准入</option></select></label>`+note('理由与后续责任'),'保存模拟决定',form=>{v.decision=form.get('decision');v.evidenceReady=false;v.taskPreview=false;v.note=form.get('note');render();toast('本地审核决定已记录，不创建任务。');});
    if(id==='preview-task'&&v.decision==='Confirm'&&v.evidenceReady){v.taskPreview=true;showDialog('TASK-001 · 条件分支中的模拟任务','目标态设计，未实际创建、分派或执行。当前演示已由用户主动完成假设补证与人工 Confirm。',`<h3>${D.taskTitle}</h3>${badge('Pending Acceptance','amber')}${facts([['拟接收方','服务运营负责人（模拟）'],['协作角色','渠道内容 / 客服知识负责人'],['独立验收','服务规范负责人，不兼任修改执行人']])}<ol class="task-preview-list">${D.taskSteps.map(e=>`<li>${e}</li>`).join('')}</ol><div class="outcome-grid"><article><h3>措施验收</h3><p>清单核对、授权修改与渠道发布证据满足验收。</p></article><article><h3>效果观察</h3><p>后续退回、旧清单引用与重复咨询仍待采集验证。</p></article></div><p class="boundary">指派不等于接收。此处不提供“执行任务”或“完成任务”的虚假成功操作。</p>`,'',null,{readOnly:true});}
  });
  document.addEventListener('input',event=>{if(event.target.id==='reply-draft')state.normal.draft=event.target.value;if(event.target.id==='human-note')state.handoff.note=event.target.value;});
  document.addEventListener('change',event=>{if(event.target.id==='receiver-permission')$('#accept-case').disabled=!event.target.checked;});
  $('#dialog-form').addEventListener('submit',event=>{event.preventDefault();if(!$('#dialog-form').reportValidity())return;const data=new FormData($('#dialog-form'));if(dialogCallback)dialogCallback(data);$('#action-dialog').close();});
  for(const id of ['dialog-close','dialog-cancel'])$('#'+id).addEventListener('click',()=>$('#action-dialog').close());
  window.addEventListener('popstate',()=>chooseView(new URL(location.href).searchParams.get('view'),false));
  chooseView(new URL(location.href).searchParams.get('view'),false);
})();
